// A second package asking for the same two instantiations at the same type
// argument. There must be one `@pkg_lib.pick$i32` and one
// `@pkg_lib.Holder$i32.get` for the whole program, not one per asking package.
import { Holder, pick } from "../pkg_lib/index";

export const fromA = (): i32 => pick(5, 50) + new Holder<i32>(2).get();
